// src/components/shared/ImageDisplay.tsx
import React, { useEffect, useState, useCallback } from 'react';
import { imageManager } from '../../services/ImageManager';
import { GameState } from '../../types/game';

interface ImageDisplayProps {
  gameState: GameState;
}

export function EnvironmentDisplay({ gameState }: ImageDisplayProps) {
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cleanupImageUrl = useCallback((url: string) => {
    try {
      URL.revokeObjectURL(url);
      console.log('Revoked Object URL:', url);
    } catch (err) {
      console.error('Failed to revoke Object URL:', err);
    }
  }, []);

  const loadImage = async () => {
    const imageId = gameState.display.environmentImageId;
    if (!imageId) {
      setImageUrl(null);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Clean up previous URL if it exists
      if (imageUrl) {
        cleanupImageUrl(imageUrl);
      }

      console.log('Fetching image:', imageId);
      const image = await imageManager.getImage(imageId);
      
      if (!image) {
        throw new Error('Image not found in storage');
      }

      console.log('Retrieved image:', image);
      console.log('Image type:', image.type);
      console.log('Image size:', image.size);

      // Create a new blob with explicit type
      const blob = new Blob([await image.arrayBuffer()], { type: image.type });
      const url = URL.createObjectURL(blob);
      console.log('Created blob URL:', url);

      // Create a promise that resolves when the image loads or rejects on error
      await new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          console.log('Image loaded successfully:', {
            width: img.width,
            height: img.height,
            src: url
          });
          resolve(true);
        };
        img.onerror = (e) => {
          console.error('Image preview failed:', e);
          reject(new Error('Failed to preview image'));
        };
        img.src = url;
      });

      setImageUrl(url);
      setError(null);
    } catch (err) {
      console.error('Error loading image:', err);
      setError(err instanceof Error ? err.message : 'Failed to load image');
      setImageUrl(null);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadImage();

    return () => {
      if (imageUrl) {
        cleanupImageUrl(imageUrl);
      }
    };
  }, [gameState.display.environmentImageId]);

  if (isLoading) {
    return (
      <div className="w-full h-96 bg-gray-100 rounded-lg flex items-center justify-center">
        <div className="flex flex-col items-center">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <span className="text-gray-500 mt-2">Loading environment...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full h-96 bg-red-50 rounded-lg flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-500 mb-2">{error}</p>
          <p className="text-gray-500 text-sm mb-4">ImageID: {gameState.display.environmentImageId}</p>
          <button
            onClick={loadImage}
            className="mt-2 px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600 transition-colors"
          >
            Retry Loading
          </button>
        </div>
      </div>
    );
  }

  if (!imageUrl) {
    return (
      <div className="w-full h-96 bg-gray-100 rounded-lg flex items-center justify-center">
        <span className="text-gray-500">No environment image selected</span>
      </div>
    );
  }

  return (
    <div className="w-full h-96 rounded-lg overflow-hidden bg-gray-100 relative">
      <img
        src={imageUrl}
        alt="Environment"
        className="w-full h-full object-contain"
        onLoad={() => {
          console.log('Image rendered successfully');
        }}
        onError={(e) => {
          console.error('Image render failed:', e);
          const target = e.target as HTMLImageElement;
          console.log('Failed image src:', target.src);
          setError('Failed to render image');
          if (imageUrl) {
            cleanupImageUrl(imageUrl);
            setImageUrl(null);
          }
        }}
      />
    </div>
  );
}