// src/components/DungeonMaster/DMView.tsx
import React, { useEffect } from 'react';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../ui/tabs';
import { DMViewProps } from '../../types/game';
import { CharacterTab } from './Tabs/CharacterTab';
import { VisualsTab } from './Tabs/VisualsTab';
import { CatalogTab } from './Tabs/CatalogTab';
import { EncounterTab } from './Tabs/EncounterTab';
import { BattleTab } from './Tabs/BattleTab';
import { CharacterActions } from '../../actions/characterActions';
import { Download } from 'lucide-react';

type TabType = 'characters' | 'visuals' | 'catalog' | 'encounter' | 'battle';

export function DMView({ gameState, onGameStateChange, room, isRoomCreator = true }: DMViewProps) {
  const tabs: { id: TabType; label: string }[] = [
    { id: 'characters', label: 'Characters' },
    { id: 'visuals', label: 'Visuals' },
    { id: 'catalog', label: 'Catalog' },
    { id: 'encounter', label: 'Encounter' },
    { id: 'battle', label: 'Battle' }
  ];

  // Handle exporting the game state
  const handleExportGameState = () => {
    const saveData = JSON.stringify(gameState, null, 2);
    const blob = new Blob([saveData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const link = document.createElement('a');
    link.href = url;
    link.download = `quest-net-save-${timestamp}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };
  // Set up action handlers for character-related actions
  useEffect(() => {
    if (!room || !isRoomCreator) return;

    // Character Creation Handler
    const [_, getCharCreate] = room.makeAction(CharacterActions.CREATE);
    getCharCreate(({ character, playerId }) => {
      console.log(`DM received character creation request from ${playerId}:`, character);
      const newId = crypto.randomUUID();
      const newCharacter = { ...character, id: newId };
      
      onGameStateChange({
        ...gameState,
        party: [...gameState.party, newCharacter]
      });
    });

    // Character Update Handler
    const [__, getCharUpdate] = room.makeAction(CharacterActions.UPDATE);
    getCharUpdate(({ id, updates, playerId }) => {
      console.log(`DM received character update request from ${playerId} for character ${id}:`, updates);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === id ? { ...char, ...updates } : char
        )
      });
    });

    // Character Delete Handler
    const [___, getCharDelete] = room.makeAction(CharacterActions.DELETE);
    getCharDelete(({ id, playerId }) => {
      console.log(`DM received character deletion request from ${playerId} for character ${id}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.filter(char => char.id !== id)
      });
    });

    // Character Selection Handler
    const [____, getCharSelect] = room.makeAction(CharacterActions.SELECT);
    getCharSelect(({ characterId, playerId }) => {
      console.log(`DM received character selection request from ${playerId} for character ${characterId}`);
      onGameStateChange({
        ...gameState,
        party: gameState.party.map(char =>
          char.id === characterId
            ? { ...char, playerId }
            : char.playerId === playerId
            ? { ...char, playerId: undefined }
            : char
        )
      });
    });

    // Cleanup function
    return () => {
      // Trystero's room.leave() will handle cleanup of action handlers
    };
  }, [room, isRoomCreator, gameState, onGameStateChange]);

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Dungeon Master Dashboard</h1>
        {isRoomCreator && (
          <button
            onClick={handleExportGameState}
            className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors gap-2"
          >
            <Download className="w-4 h-4" />
            Export Save File
          </button>
        )}
      </div>

      <Tabs defaultValue="characters" className="w-full">
        <TabsList className="w-full flex justify-start border-b border-gray-200 bg-transparent">
          {tabs.map(({ id, label }) => (
            <TabsTrigger
              key={id}
              value={id}
              className="px-4 py-2 text-sm font-medium data-[state=active]:border-b-2 data-[state=active]:border-blue-500 data-[state=active]:text-blue-600"
            >
              {label}
            </TabsTrigger>
          ))}
        </TabsList>

        <TabsContent value="characters">
          <CharacterTab 
            gameState={gameState} 
            onGameStateChange={onGameStateChange} 
            room={room}
            isRoomCreator={isRoomCreator}
          />
        </TabsContent>

        <TabsContent value="visuals">
        <VisualsTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={true}
          />
        </TabsContent>

        <TabsContent value="catalog">
          <CatalogTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            
          />
        </TabsContent>

        <TabsContent value="encounter">
          <EncounterTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            
          />
        </TabsContent>

        <TabsContent value="battle">
          <BattleTab 
            gameState={gameState}
            onGameStateChange={onGameStateChange}
            room={room}
            isRoomCreator={isRoomCreator}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
}