// src/components/Player/PlayerView.tsx
import React, { useEffect, useState } from 'react';
import { CharacterSelect } from './CharacterSelect';
import { CharacterSheet } from './CharacterSheet';
import { CharacterEditor } from '../shared/CharacterEditor';
import { useCharacterActions } from '../../actions/characterActions';
import { Character, PlayerViewProps } from '../../types/game';
import { EnvironmentDisplay } from '../shared/ImageDisplay';
import { useImageSync } from '../../hooks/useImageSync';
import { useEnvImageSync } from '../../hooks/useEnvImageSync';


export function PlayerView({ gameState, playerId, onCharacterSelect, room }: PlayerViewProps) {
  const [selectedCharacter, setSelectedCharacter] = useState<Character | null>(null);
  const [showEditor, setShowEditor] = useState(false);
  const [editorCharacter, setEditorCharacter] = useState<Character | undefined>();
  const actions = useCharacterActions(room, gameState, () => {}, false);
  
  // Add environment image sync
  useEnvImageSync(room, gameState);
  useImageSync(room, false);

  useEffect(() => {
    const character = gameState.party.find(c => c.playerId === playerId);
    setSelectedCharacter(character || null);
  }, [gameState, playerId]);
  
  useEffect(() => {
    const character = gameState.party.find(c => c.playerId === playerId);
    setSelectedCharacter(character || null);
  }, [gameState, playerId]);

  const handleCreateCharacter = async (character: Omit<Character, 'id'>) => {
    await actions.createCharacter(character);
    setShowEditor(false);
  };

  const handleUpdateCharacter = async (id: string, updates: Partial<Character>) => {
    await actions.updateCharacter(id, updates);
    setShowEditor(false);
  };

  const handleSelectCharacter = async (characterId: string) => {
    await actions.selectCharacter(characterId);
    onCharacterSelect(characterId);
  };

  const renderContent = () => {
    if (showEditor) {
      return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold">
                {editorCharacter ? 'Edit Character' : 'Create Character'}
              </h3>
            </div>
            
            <CharacterEditor
              character={editorCharacter}
              onSave={handleCreateCharacter}
              onUpdate={handleUpdateCharacter}
              onClose={() => {
                setShowEditor(false);
                setEditorCharacter(undefined);
              }}
              isRoomCreator={false}
            />
          </div>
        </div>
      );
    }

    if (selectedCharacter) {
      return (
        <div className="space-y-4">
          <CharacterSheet character={selectedCharacter} />
          <button
            onClick={() => {
              setEditorCharacter(selectedCharacter);
              setShowEditor(true);
            }}
            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
          >
            Edit Character
          </button>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <CharacterSelect
          party={gameState.party}
          playerId={playerId}
          onSelect={handleSelectCharacter}
        />
        <div className="flex justify-center">
          <button
            onClick={() => {
              setEditorCharacter(undefined);
              setShowEditor(true);
            }}
            className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700"
          >
            Create New Character
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Add EnvironmentDisplay at the top */}
      <div className="mb-6">
      <EnvironmentDisplay 
        gameState={gameState}
      />
      </div>

      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold">Player View</h2>
      </div>
      {renderContent()}
    </div>
  );
  
}