// hooks/usePeerSync.ts
import { useCallback, useRef, useState } from 'react';
import { selfId } from 'trystero';
import type { Room } from '../types/room';
import { GameState, SerializableSaveState, initialGameState } from '../types/game';


export function usePeerSync(isRoomCreator: boolean) {
  const [gameState, setGameState] = useState<GameState>(initialGameState);
  const gameStateRef = useRef<GameState>(initialGameState);
  const sendGameStateRef = useRef<(state: SerializableSaveState, target?: string | string[]) => void>();

  const broadcastGameState = useCallback(() => {
    if (isRoomCreator && sendGameStateRef.current) {
      const currentState: SerializableSaveState = {
        gameState: gameStateRef.current,
        lastModified: Date.now(),
        roomCreator: selfId
      };
      sendGameStateRef.current(currentState);
    }
  }, [isRoomCreator]);

  const handleGameStateChange = useCallback((newState: GameState) => {
    gameStateRef.current = newState;
    setGameState(newState);
    broadcastGameState();
  }, [broadcastGameState]);

  const initializePeerSync = useCallback((room: Room) => {
    const [sendGameState, getGameState] = room.makeAction<SerializableSaveState>('gameState');
    const [requestGameState, getStateRequest] = room.makeAction<{ from: string }>('requestState');
    
    sendGameStateRef.current = sendGameState;

    getGameState((state, peerId) => {
      console.log('Received game state from:', peerId, state);
      gameStateRef.current = state.gameState;
      setGameState(state.gameState);
    });

    getStateRequest((data, peerId) => {
      if (isRoomCreator && sendGameStateRef.current) {
        const currentState: SerializableSaveState = {
          gameState: gameStateRef.current,
          lastModified: Date.now(),
          roomCreator: selfId
        };
        sendGameStateRef.current(currentState, peerId);
      }
    });

    room.onPeerJoin(peerId => {
      if (!isRoomCreator) {
        requestGameState({ from: selfId }, peerId);
      } else {
        const currentState: SerializableSaveState = {
          gameState: gameStateRef.current,
          lastModified: Date.now(),
          roomCreator: selfId
        };
        sendGameState(currentState, peerId);
      }
    });
  }, [isRoomCreator]);

  return {
    gameState,
    setGameState,
    handleGameStateChange,
    broadcastGameState,
    initializePeerSync,
  };
}