import React from 'react';
import { Star } from 'lucide-react';

// Shared logic for all toggle variants
function useTheme() {
  const [isDark, setIsDark] = React.useState(() => {
    if (typeof window !== 'undefined') {
      return document.documentElement.classList.contains('dark');
    }
    return false;
  });

  const toggleTheme = () => {
    setIsDark(!isDark);
    if (isDark) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    }
  };

  React.useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    
    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      document.documentElement.classList.add('dark');
      setIsDark(true);
    }
  }, []);

  return { isDark, toggleTheme };
}

// Variant 1: Sliding Switch
export function SlidingToggle() {
  const { isDark, toggleTheme } = useTheme();
  
  return (
    <button
      onClick={toggleTheme}
      className={`
        relative inline-flex h-8 w-20 items-center rounded-[0.9rem]
        border-2 border-[#333233] dark:border-[#F2EEE4]
        bg-[#F2EEE4] dark:bg-[#333233]
        transition-colors duration-300
      `}
      aria-label="Toggle theme"
    >
      <span 
        className={`
          ${isDark ? 'translate-x-12' : 'translate-x-1'}
          inline-flex items-center justify-center
          h-6 w-6 transform
          rounded-full
          border border-[#333233] dark:border-[#F2EEE4]
          bg-[#333233] dark:bg-[#F2EEE4]
          transition duration-300
        `}
      >
        {isDark ? (
          <svg
            className="h-4 w-4"
            width="20" height="20" 
            viewBox="0 0 20 20" 
            fill="none" 
            xmlns="http://www.w3.org/2000/svg"
          >
            <path 
              d="M10 0L12.1213 7.87868L20 10L12.1213 12.1213L10 20L7.87868 12.1213L0 10L7.87868 7.87868L10 0Z" 
              fill="#333233"
            />
          </svg>
        ) : (
          <svg
            className="h-4 w-4"
            width="20" height="20" 
            viewBox="0 0 20 20" 
            fill="none" 
            xmlns="http://www.w3.org/2000/svg"
          >
            <path 
              d="M10 0L12.1213 7.87868L20 10L12.1213 12.1213L10 20L7.87868 12.1213L0 10L7.87868 7.87868L10 0Z" 
              fill="#F2EEE4"
            />
          </svg>
        )}
      </span>
    </button>
  );
}



// Default export showing all variants
export default function ThemeToggles() {
  return (
    <div className="fixed top-4 right-4 flex flex-col gap-4">
      <SlidingToggle />
    </div>
  );
}