// src/hooks/useEnvImageSync.ts
import { useEffect } from 'react';
import type { Room } from 'trystero/torrent';
import { imageManager } from '../services/ImageManager';
import type { GameState } from '../types/game';

export function useEnvImageSync(room: Room | undefined, gameState: GameState) {
  useEffect(() => {
    if (!room || !gameState.display.environmentImageId) return;

    const checkAndRequestImage = async () => {
      const imageId = gameState.display.environmentImageId;
      if (!imageId) return;

      // Check if we already have the image locally
      const existingImage = await imageManager.getImage(imageId);
      if (existingImage) return;

      console.log('Missing environment image, requesting:', imageId);

      // Setup action handlers for requesting and receiving the image
      const [sendImageRequest, getImageRequest] = room.makeAction('requestEnvImage');
      const [sendImage, getImage] = room.makeAction('envImage');

      // Request the image from other peers
      await sendImageRequest(imageId);

      // Handle image response
      getImage(async (imageData: File, peerId, metadata) => {
        console.log('Received environment image from peer:', peerId, metadata);
        if (!metadata?.imageId) return;

        try {
          await imageManager.addReceivedImage(imageData, {
            id: metadata.imageId,
            name: metadata.name || 'environment.jpg',
            description: `Received environment image from ${peerId}`,
            createdAt: Date.now(),
            size: imageData.size,
            type: imageData.type,
            thumbnail: metadata.thumbnail
          });
        } catch (err) {
          console.error('Failed to process received environment image:', err);
        }
      });

      // Handle image requests from other peers
      getImageRequest(async (requestedImageId, peerId) => {
        console.log('Received image request from peer:', peerId, requestedImageId);
        const image = await imageManager.getImage(requestedImageId);
        if (!image) return;

        const imageData = await imageManager.getImageData(requestedImageId);
        if (!imageData) return;

        console.log('Sending requested image to peer:', peerId);
        await sendImage(image, peerId, {
          imageId: requestedImageId,
          name: image.name,
          thumbnail: imageData.thumbnail
        });
      });
    };

    checkAndRequestImage();
  }, [room, gameState.display.environmentImageId]);
}