// src/hooks/useImageSync.ts
import { useEffect } from 'react';
import { Room } from 'trystero/torrent';
import { imageManager } from '../services/ImageManager';

interface ImageChunk {
  imageId: string;
  chunk: number[];
  index: number;
  total: number;
  metadata: {
    type: string;
    name: string;
    size: number;
    originalSize: number;  // Add original size for reference
    originalType: string;  // Add original type for reference
  };
  thumbnail: string;
}

const CHUNK_SIZE = 256 * 1024;
const PARALLEL_CHUNKS = 3;
const CHUNK_DELAY = 20;

// Compression configuration
const COMPRESSION_QUALITY = 0.7;  // 0.0 to 1.0
const MAX_DIMENSION = 2048;      // Max width/height for large images

async function compressImage(file: File): Promise<{ file: File; compressionStats: any }> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    img.onload = () => {
      // Calculate dimensions while maintaining aspect ratio
      let width = img.width;
      let height = img.height;
      
      if (width > MAX_DIMENSION || height > MAX_DIMENSION) {
        if (width > height) {
          height *= MAX_DIMENSION / width;
          width = MAX_DIMENSION;
        } else {
          width *= MAX_DIMENSION / height;
          height = MAX_DIMENSION;
        }
      }

      canvas.width = width;
      canvas.height = height;

      // Draw and compress
      ctx!.drawImage(img, 0, 0, width, height);
      
      // Convert to JPEG for better compression
      const compressedDataUrl = canvas.toDataURL('image/jpeg', COMPRESSION_QUALITY);
      
      // Convert base64 to blob
      fetch(compressedDataUrl)
        .then(res => res.blob())
        .then(blob => {
          const compressedFile = new File([blob], file.name, {
            type: 'image/jpeg',
            lastModified: Date.now()
          });

          const compressionStats = {
            originalSize: file.size,
            compressedSize: compressedFile.size,
            compressionRatio: (file.size / compressedFile.size).toFixed(2),
            originalDimensions: `${img.width}x${img.height}`,
            compressedDimensions: `${width}x${height}`,
            qualityUsed: COMPRESSION_QUALITY
          };

          console.log('Compression stats:', compressionStats);
          resolve({ file: compressedFile, compressionStats });
        })
        .catch(reject);
    };

    img.onerror = () => reject(new Error('Failed to load image for compression'));

    // Load image from file
    const reader = new FileReader();
    reader.onload = (e) => img.src = e.target!.result as string;
    reader.onerror = () => reject(new Error('Failed to read image file'));
    reader.readAsDataURL(file);
  });
}

export function useImageSync(room: Room | undefined, isRoomCreator: boolean) {
  useEffect(() => {
    if (!room) return;

    console.log('Setting up image sync - isRoomCreator:', isRoomCreator);
    
    const [sendImageChunk, getImageChunk] = room.makeAction<ImageChunk>('imageChunk');
    const chunks = new Map<string, Map<number, Uint8Array>>();
    const metadata = new Map<string, { meta: ImageChunk['metadata']; thumbnail: string }>();
    const transferProgress = new Map<string, { received: number; total: number }>();

    // Receiver code remains mostly the same, but adds original metadata handling
    getImageChunk(async ({ imageId, chunk, index, total, metadata: meta, thumbnail }) => {
      try {
        // Progress tracking
        if (!transferProgress.has(imageId)) {
          transferProgress.set(imageId, { received: 0, total });
          console.log(`Starting transfer of image ${imageId} (${meta.size} bytes, original: ${meta.originalSize} bytes)`);
        }

        const progress = transferProgress.get(imageId)!;
        progress.received++;
        const percentComplete = Math.round((progress.received / total) * 100);
        console.log(`Image ${imageId}: ${percentComplete}% complete (${progress.received}/${total} chunks)`);

        if (!chunks.has(imageId)) {
          chunks.set(imageId, new Map());
          metadata.set(imageId, { meta, thumbnail });
        }

        const uint8Chunk = new Uint8Array(chunk);
        chunks.get(imageId)!.set(index, uint8Chunk);

        if (progress.received === total) {
          console.log(`Reconstructing image ${imageId}`);
          const imageChunks = chunks.get(imageId)!;
          const totalSize = meta.size;
          const completeBuffer = new Uint8Array(totalSize);
          let position = 0;

          for (let i = 0; i < total; i++) {
            const chunk = imageChunks.get(i)!;
            completeBuffer.set(chunk, position);
            position += chunk.length;
          }

          const file = new File([completeBuffer], meta.name, { 
            type: meta.type,
            lastModified: Date.now()
          });

          const imageData = {
            id: imageId,
            name: meta.name,
            description: `Received image: ${meta.name} (Original: ${meta.originalType}, ${meta.originalSize} bytes)`,
            createdAt: Date.now(),
            size: meta.size,
            type: meta.type,
            thumbnail: metadata.get(imageId)!.thumbnail
          };

          await imageManager.addReceivedImage(file, imageData);
          console.log(`Successfully reconstructed image ${imageId}`);

          chunks.delete(imageId);
          metadata.delete(imageId);
          transferProgress.delete(imageId);
        }
      } catch (error) {
        console.error('Failed to process image chunk:', error);
        chunks.delete(imageId);
        metadata.delete(imageId);
        transferProgress.delete(imageId);
      }
    });

    // Sender code with compression
    if (isRoomCreator) {
      (window as any).broadcastImage = async (imageId: string) => {
        console.log('Starting image broadcast for:', imageId);
        const startTime = performance.now();
        
        try {
          const originalImage = await imageManager.getImage(imageId);
          const imageData = await imageManager.getImageData(imageId);
          
          if (!originalImage || !imageData) {
            throw new Error('Image or image data not found for broadcast');
          }

          // Compress image before sending
          console.log('Compressing image...');
          const { file: compressedImage, compressionStats } = await compressImage(originalImage);
          console.log('Compression complete:', compressionStats);

          const buffer = await compressedImage.arrayBuffer();
          const chunksArray = new Uint8Array(buffer);
          const totalChunks = Math.ceil(chunksArray.length / CHUNK_SIZE);
          
          console.log(`Broadcasting compressed image ${imageId}:`, {
            originalSize: originalImage.size,
            compressedSize: compressedImage.size,
            compressionRatio: compressionStats.compressionRatio,
            chunks: totalChunks
          });

          const chunks = Array.from({ length: totalChunks }, (_, i) => {
            const start = i * CHUNK_SIZE;
            const end = Math.min(start + CHUNK_SIZE, chunksArray.length);
            return {
              index: i,
              data: Array.from(chunksArray.slice(start, end))
            };
          });

          // Send chunks in parallel
          for (let i = 0; i < chunks.length; i += PARALLEL_CHUNKS) {
            const batch = chunks.slice(i, i + PARALLEL_CHUNKS);
            await Promise.all(batch.map(chunk => 
              sendImageChunk({
                imageId,
                chunk: chunk.data,
                index: chunk.index,
                total: totalChunks,
                metadata: {
                  type: compressedImage.type,
                  name: originalImage.name,
                  size: buffer.byteLength,
                  originalSize: originalImage.size,
                  originalType: originalImage.type
                },
                thumbnail: imageData.thumbnail
              }).then(() => new Promise(resolve => setTimeout(resolve, CHUNK_DELAY)))
            ));
            
            const progress = Math.round(((i + batch.length) / totalChunks) * 100);
            console.log(`Upload progress: ${progress}%`);
          }

          const totalTime = (performance.now() - startTime) / 1000;
          console.log(`Finished broadcasting image in ${totalTime.toFixed(2)}s`, {
            originalSize: originalImage.size,
            compressedSize: compressedImage.size,
            compressionRatio: compressionStats.compressionRatio,
            transferSpeed: ((compressedImage.size / 1024 / 1024) / totalTime).toFixed(2) + ' MB/s'
          });
        } catch (error) {
          console.error('Failed to broadcast image:', error);
        }
      };
    }

    return () => {
      if (isRoomCreator) {
        delete (window as any).broadcastImage;
      }
    };
  }, [room, isRoomCreator]);
}