// src/components/GameInterface.tsx
import React, { ReactNode } from 'react';
import type { ConnectionStatusType } from '../types/connection';

interface GameInterfaceProps {
  roomId: string;
  peers: string[];
  connectionStatus: ConnectionStatusType;
  errorMessage: string;
  isRoomCreator: boolean;
  onLeaveRoom: () => void;
  onSaveGame: () => void;
  children: ReactNode;
}

export function GameInterface({
  roomId,
  peers,
  connectionStatus,
  errorMessage,
  isRoomCreator,
  onLeaveRoom,
  onSaveGame,
  children
}: GameInterfaceProps) {
  const getStatusColor = () => {
    switch (connectionStatus) {
      case 'connected':
        return '#22c55e';
      case 'connecting':
      case 'reconnecting':
        return '#3b82f6';
      case 'error':
        return '#ef4444';
      default:
        return '#6b7280';
    }
  };

  const getConnectionStatusDisplay = () => {
    const statusColor = getStatusColor();
    const statusText = connectionStatus === 'connected'
      ? `Connected ${peers.length === 0 
          ? "(No other peers)" 
          : `(${peers.length} peer${peers.length === 1 ? '' : 's'})`}`
      : connectionStatus === 'connecting'
      ? "Connecting..."
      : connectionStatus === 'reconnecting'
      ? "Reconnecting..."
      : connectionStatus === 'error'
      ? `Error: ${errorMessage}`
      : "Disconnected";

    return (
      <div 
        style={{
          padding: '10px',
          marginBottom: '15px',
          border: `1px solid ${statusColor}`,
          borderRadius: '4px',
          backgroundColor: `${statusColor}10`,
          color: statusColor,
          display: 'flex',
          alignItems: 'center',
          gap: '8px'
        }}
      >
        <div 
          style={{
            width: '8px',
            height: '8px',
            borderRadius: '50%',
            backgroundColor: statusColor,
            animation: (connectionStatus === 'connecting' || 
                       connectionStatus === 'reconnecting') 
              ? 'pulse 1.5s infinite' 
              : 'none'
          }}
        />
        <span>{statusText}</span>
        {isRoomCreator && <span style={{ marginLeft: 'auto', fontSize: '0.8em' }}>(Room Creator)</span>}
      </div>
    );
  };

  return (
    <div style={{ padding: '1rem', maxWidth: '40rem', margin: '0 auto' }}>
      <style>
        {`
          @keyframes pulse {
            0% { opacity: 1; }
            50% { opacity: 0.3; }
            100% { opacity: 1; }
          }
        `}
      </style>

      <div style={{ marginBottom: '1rem' }}>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 'bold', marginBottom: '1rem' }}>
          Game Room: {roomId}
        </h1>
        {getConnectionStatusDisplay()}
        <div style={{ marginBottom: '1rem' }}>
          <button
            onClick={onLeaveRoom}
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#ef4444',
              color: '#ffffff',
              border: 'none',
              borderRadius: '0.375rem',
              cursor: 'pointer'
            }}
          >
            Leave Room
          </button>
          {isRoomCreator && (
            <button
              onClick={onSaveGame}
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: '#22c55e',
                color: '#ffffff',
                border: 'none',
                borderRadius: '0.375rem',
                cursor: 'pointer',
                marginLeft: '1rem'
              }}
            >
              Save Game
            </button>
          )}
        </div>
      </div>

      <div style={{ 
        padding: '2rem',
        
      }}>
        {children}
      </div>
    </div>
  );
}