// components/DungeonMaster/CharacterList.tsx
import React from 'react';
import { Character } from '../../types/game';

interface CharacterListProps {
  party: Character[];
  onSelectCharacter: (id: string) => void;
}

export function CharacterList({ party, onSelectCharacter }: CharacterListProps) {
  return (
    <div className="space-y-4">
      <h2 className="text-xl font-bold">Party Members</h2>
      <div className="grid gap-4">
        {party.map(character => (
          <div 
            key={character.id}
            className="p-4 border rounded-lg bg-white shadow-sm"
            onClick={() => onSelectCharacter(character.id)}
          >
            <div className="flex justify-between items-center">
              <h3 className="font-medium">{character.name}</h3>
              <span className="text-sm">
                HP: {character.hp}/{character.maxHp}
              </span>
            </div>
            <p className="text-sm text-gray-600 mt-2">{character.description}</p>
            {character.playerId && (
              <div className="text-sm text-blue-600 mt-2">
                Currently played by: {character.playerId}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}