// components/Player/CharacterSelect.tsx
import React from 'react';
import { Character } from '../../types/game';
interface CharacterSelectProps {
 party: Character[];
 playerId: string;
 onSelect: (characterId: string) => void;
}

export function CharacterSelect({ party, playerId, onSelect }: CharacterSelectProps) {
 const availableCharacters = party.filter(char => !char.playerId || char.playerId === playerId);

 return (
   <div className="space-y-4">
     <h2 className="text-xl font-bold">Select Your Character</h2>
     <div className="grid gap-4">
       {availableCharacters.map(character => (
         <button
           key={character.id}
           onClick={() => onSelect(character.id)}
           className="p-4 border rounded-lg text-left hover:bg-gray-50"
         >
           <h3 className="font-medium">{character.name}</h3>
           <p className="text-sm text-gray-600 mt-2">{character.description}</p>
           <div className="text-sm mt-2">HP: {character.hp}/{character.maxHp}</div>
         </button>
       ))}
       {availableCharacters.length === 0 && (
         <p className="text-gray-600">No available characters to select.</p>
       )}
     </div>
   </div>
 );
}